/**
 * Change classification: decide what a diff means for the matrix.
 *
 * Fails safe in every ambiguous case. Over-selecting costs runner time;
 * under-selecting ships untested code, so any uncertainty resolves to the full
 * matrix.
 *
 * @module
 */

import type { Extension } from "./discover.ts";

export type Scope = "full" | "scoped";

export interface Classification {
  scope: Scope;
  /** Extension directories to build. Every extension when scope is "full". */
  extensions: string[];
  /** Human-readable explanation, surfaced in the workflow log. */
  reason: string;
  /**
   * True when the selection exceeds MATRIX_LIMIT and cannot be expressed as a
   * single GitHub matrix.
   *
   * Deliberately NOT resolved by truncating. Silently dropping entries would
   * mean silently not testing them, which is the failure mode every other
   * decision here is designed to avoid. The caller must fail instead, and the
   * repo needs chunked or nested matrices at that point.
   */
  overflow: boolean;
}

/**
 * GitHub caps a matrix at 256 jobs per workflow run. 137 extensions as one job
 * each fits; 137 x 4 tasks as a matrix axis would not, which is why tasks are
 * steps rather than a dimension.
 */
export const MATRIX_LIMIT = 256;

/**
 * Classify a set of changed paths.
 *
 * `changed` is repo-root-relative paths. A null or empty list means the diff
 * could not be computed, which selects the full matrix rather than guessing that
 * nothing changed.
 */
export function classify(
  changed: string[] | null,
  exts: Extension[],
  expand: (seed: Iterable<string>) => string[],
): Classification {
  const allDirs = exts.map((e) => e.dir);

  const full = (reason: string): Classification => ({
    scope: "full",
    extensions: allDirs,
    reason,
    overflow: allDirs.length > MATRIX_LIMIT,
  });

  if (changed === null) return full("diff could not be computed");
  if (changed.length === 0) return full("empty diff");

  // Longest-prefix match, so `cloudflare/kv/...` attributes to `cloudflare/kv`
  // rather than to the shorter `cloudflare` that also prefixes it.
  const dirsByLength = [...allDirs].sort((a, b) => b.length - a.length);

  const touched = new Set<string>();
  const global: string[] = [];

  for (const path of changed) {
    const owner = dirsByLength.find((d) =>
      path === d || path.startsWith(d + "/")
    );
    if (owner) touched.add(owner);
    else global.push(path);
  }

  if (global.length > 0) {
    const sample = global.slice(0, 3).join(", ");
    return full(
      `shared file changed outside every extension: ${sample}` +
        (global.length > 3 ? ` (+${global.length - 3} more)` : ""),
    );
  }

  const expanded = expand(touched);
  const added = expanded.filter((d) => !touched.has(d));
  const reason = added.length > 0
    ? `${touched.size} extension(s) changed, +${added.length} dependent(s): ${
      added.join(", ")
    }`
    : `${touched.size} extension(s) changed, no dependents`;

  return {
    scope: "scoped",
    extensions: expanded,
    reason,
    overflow: expanded.length > MATRIX_LIMIT,
  };
}
/**
 * Reverse-dependency expansion.
 *
 * Nine extensions declare dependencies on fifteen others, and `aws/inventory`
 * alone has four dependents. Diff-scoping without expansion would test a change
 * to it in isolation and report green while its dependents were never built.
 *
 * @module
 */

import { type Extension, nameToDir, stripVersion } from "./discover.ts";

/**
 * Build dependents edges: directory -> directories that depend on it.
 *
 * Dependency specifiers naming an extension outside this repo are ignored — they
 * cannot be built here, so they cannot be affected by a local change.
 */
export function buildDependents(exts: Extension[]): Map<string, Set<string>> {
  const byName = nameToDir(exts);
  const dependents = new Map<string, Set<string>>();

  for (const ext of exts) {
    for (const spec of ext.dependencies) {
      const depDir = byName.get(stripVersion(spec));
      if (!depDir) continue; // external or unresolvable
      if (depDir === ext.dir) continue; // self-reference, ignore
      let set = dependents.get(depDir);
      if (!set) {
        set = new Set();
        dependents.set(depDir, set);
      }
      set.add(ext.dir);
    }
  }

  return dependents;
}

/**
 * Expand a seed set to include everything that transitively depends on it.
 *
 * Breadth-first with a visited set, so a dependency cycle terminates instead of
 * looping. Cycles are not currently present but nothing prevents one being
 * introduced, and a CI script that hangs is worse than one that over-selects.
 */
export function expandDependents(
  seed: Iterable<string>,
  dependents: Map<string, Set<string>>,
): string[] {
  const selected = new Set<string>(seed);
  const queue = [...selected];

  while (queue.length > 0) {
    const dir = queue.shift()!;
    for (const dep of dependents.get(dir) ?? []) {
      if (selected.has(dep)) continue;
      selected.add(dep);
      queue.push(dep);
    }
  }

  return [...selected].sort((a, b) => a.localeCompare(b));
}
/**
 * Extension discovery.
 *
 * Coverage is derived from the filesystem rather than from hand-maintained
 * matrix lists in ci.yml, which is how 55 of 137 extensions ended up with no CI
 * job at all.
 *
 * @module
 */

/** An extension found on disk. */
export interface Extension {
  /** Directory relative to the repo root, e.g. "aws/inventory". */
  dir: string;
  /** Published name from manifest.yaml, e.g. "@webframp/aws/inventory". */
  name: string;
  /** Raw dependency specifiers, e.g. "@webframp/aws/logs@2026.07.21.1". */
  dependencies: string[];
}

/**
 * Maximum directory depth searched for manifest.yaml.
 *
 * This repo nests two deep (`aws/adopt`, `cloudflare/kv`, `datastore/postgres`).
 * A single-level scan finds 36 of 137 and silently drops the rest.
 */
export const MAX_DEPTH = 2;

/** Read `name` from a manifest. Minimal parse — no YAML dependency. */
export function parseManifestName(text: string): string | null {
  const m = text.match(/^name:\s*"?([^"\n]+?)"?\s*$/m);
  return m ? m[1].trim() : null;
}

/**
 * Read the `dependencies:` block from a manifest.
 *
 * Entries look like `- "@webframp/aws/logs@2026.07.21.1"`. Parsing stops at the
 * next top-level key so a later list (labels, platforms) is not absorbed.
 */
export function parseManifestDependencies(text: string): string[] {
  const lines = text.split("\n");
  const deps: string[] = [];
  let inBlock = false;

  for (const line of lines) {
    if (/^dependencies:\s*$/.test(line)) {
      inBlock = true;
      continue;
    }
    if (!inBlock) continue;

    // A non-indented, non-empty line ends the block.
    if (/^\S/.test(line)) break;

    const item = line.match(/^\s+-\s*"?([^"\n]+?)"?\s*$/);
    if (item) deps.push(item[1].trim());
  }

  return deps;
}

/**
 * Strip the version suffix from a dependency specifier.
 *
 * Specifiers are `@collective/path@version`. The leading `@` means the version
 * separator is the LAST `@`, not the first.
 */
export function stripVersion(spec: string): string {
  const at = spec.lastIndexOf("@");
  return at > 0 ? spec.slice(0, at) : spec;
}

/** Directory reader, injectable so tests can run against a fixture tree. */
export interface FsLike {
  readDir(path: string): Iterable<{ name: string; isDirectory: boolean }>;
  readTextFile(path: string): string;
  exists(path: string): boolean;
}

/** Default FsLike backed by Deno, used outside tests. */
export const denoFs: FsLike = {
  readDir(path) {
    const out: { name: string; isDirectory: boolean }[] = [];
    for (const e of Deno.readDirSync(path)) {
      out.push({ name: e.name, isDirectory: e.isDirectory });
    }
    return out;
  },
  readTextFile: (p) => Deno.readTextFileSync(p),
  exists(p) {
    try {
      Deno.statSync(p);
      return true;
    } catch {
      return false;
    }
  },
};

/**
 * Find every extension under `root`, to MAX_DEPTH.
 *
 * Skips dotted directories and node_modules so a nested `.swamp/` cache or a
 * worktree cannot register as an extension. Results are sorted by dir so matrix
 * output is deterministic.
 */
export function discoverExtensions(
  root: string,
  fs: FsLike = denoFs,
): Extension[] {
  const found: Extension[] = [];

  const visit = (rel: string, depth: number) => {
    const abs = rel ? `${root}/${rel}` : root;

    const manifest = `${abs}/manifest.yaml`;
    if (rel && fs.exists(manifest)) {
      const text = fs.readTextFile(manifest);
      const name = parseManifestName(text);
      if (name) {
        found.push({
          dir: rel,
          name,
          dependencies: parseManifestDependencies(text),
        });
      }
      // Deliberately does NOT return. `cloudflare` is itself an extension AND
      // the parent of 26 sibling extensions (`cloudflare/kv`, ...), so treating
      // an extension directory as a leaf would drop all of them.
      //
      // What keeps an extension's own internal manifests out is depth: every
      // real extension manifest in this repo sits at depth 1 or 2, while an
      // internal one (e.g. aws/inventory/extensions/models/manifest.yaml) sits
      // at 4 or deeper.
    }

    if (depth >= MAX_DEPTH) return;

    for (const entry of fs.readDir(abs)) {
      if (!entry.isDirectory) continue;
      if (entry.name.startsWith(".") || entry.name === "node_modules") continue;
      visit(rel ? `${rel}/${entry.name}` : entry.name, depth + 1);
    }
  };

  visit("", 0);
  found.sort((a, b) => a.dir.localeCompare(b.dir));
  return found;
}

/**
 * Map published name to directory.
 *
 * Required rather than convenient: the directory does NOT mirror the name for
 * several families — `vault/pass` publishes as `@webframp/pass`,
 * `datastore/postgres` as `@webframp/postgres-datastore`.
 * Deriving a path from a dependency specifier would miss all of them.
 */
export function nameToDir(exts: Extension[]): Map<string, string> {
  const map = new Map<string, string>();
  for (const e of exts) map.set(e.name, e.dir);
  return map;
}

